from pathlib import Path
import base64,hashlib,json,zlib
PAYLOAD=''
WORLD_TEST="import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport fs from 'node:fs';\nimport crypto from 'node:crypto';\nconst c=JSON.parse(fs.readFileSync(new URL('../data/game.json',import.meta.url)));\nconst p=JSON.parse(fs.readFileSync(new URL('../data/presentation.json',import.meta.url)));\nconst places=c.events.filter(e=>e.id.startsWith('place.'));\nconst banned=['先把眼前的难处处理好','亲自动手试一试','沿岸再走一段','用自己的衣物护住东西','收紧行囊离开','取一件趁手的旧物','把修补的方法记下来','付钱换一个确定的结果','押上气血辨认真伪','让旧日受助的人作证','不接这场买卖','循声而下','留在入口听完这一阵风','赶在变化前进入','只拾起散落的灵石','顺着封印最薄处探手','以气血承受残留的力量','封好门，带走所得的见识'];\nconst strip=x=>Array.isArray(x)?x.map(strip):x&&typeof x==='object'?Object.fromEntries(Object.entries(x).filter(([k])=>!['name','npc','art','text','preview','label','consequence'].includes(k)).map(([k,v])=>[k,strip(v)])):x;\ntest('all twelve place events use scene-specific player verbs instead of repeated template labels',()=>{assert.equal(places.length,12);const labels=places.flatMap(e=>e.phases.flatMap(ph=>ph.choices.map(ch=>ch.label)));for(const x of banned)assert(!labels.includes(x),x);});\ntest('place-event prose pass does not change rewards checks conditions or phase routing',()=>{const body=JSON.stringify(places.map(strip),Object.keys({}));const stable=JSON.stringify(places.map(strip));const fp=crypto.createHash('sha256').update(JSON.stringify(places.map(strip),Object.keys({}))).digest('hex');assert(stable.length>1000);/* fingerprint is checked below with canonical sorting */});\ntest('place event aftermath is authored per scene rather than falling back to stock copy',()=>{const stock='你停在这段因果之外，待呼吸平稳，继续沿路前行。';const seen=[];for(const e of places){const copy=p.events[e.id];assert(copy);for(const v of Object.values(copy.choices))for(const k of ['outcome','success','failure'])if(v[k]){assert.notEqual(v[k],stock);seen.push(v[k]);}}assert(seen.length>=60);assert(new Set(seen).size>=seen.length-2);});\ntest('place-event mechanics fingerprint remains locked for the prose-only stage',()=>{const canon=x=>Array.isArray(x)?x.map(canon):x&&typeof x==='object'?Object.fromEntries(Object.entries(x).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>[k,canon(v)])):x;const s=JSON.stringify(canon(places.map(strip)));assert.equal(crypto.createHash('sha256').update(s).digest('hex'),'9d14fea08191085bb935001aa3b0859dc331bbe3718ca3a6f713df9c24480452');});\n"
DOC_APPEND='\n## 阶段五：地点事件文本重构\n- 保留 12 个既有地点事件的奖励、检定、条件和阶段路由，仅重写场景、动作动词、成功/失败与事后文本。\n- 朝歌夜渡、陈塘药棚、西岐军械铺、万仙遗市四条三阶段事件不再共用同一套“帮忙/动手/离开”模板。\n- 四幕交易与四处秘境分别拥有与地点一致的检定叙事；测试锁定事件机制指纹，防止文案改动误伤数值。\n'
README_APPEND='\n内容文本已完成地点事件去模板化：12 个地点事件保留原机制，改为各幕独立叙事。\n'
root=Path('.')
gp=root/'data/game.json';pp=root/'data/presentation.json'
g=json.loads(gp.read_text());p=json.loads(pp.read_text())
assert g.get('version')=='4.0.0' and p.get('revision')=='16.0'
ids=[e['id'] for e in g['events'] if e['id'].startswith('place.')]
assert len(ids)==12
def strip_text(x):
 if isinstance(x,dict):return {k:strip_text(v) for k,v in x.items() if k not in {'name','npc','art','text','preview','label','consequence'}}
 if isinstance(x,list):return [strip_text(v) for v in x]
 return x
def mechanics():return json.dumps([strip_text(e) for e in g['events'] if e['id'].startswith('place.')],sort_keys=True,separators=(',',':'),ensure_ascii=False)
before=mechanics()
d=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
byid={e['id']:e for e in g['events']}
for eid,ed in d['events'].items():
 e=byid[eid];e['text']=ed['text'];phs={x['id']:x for x in e['phases']}
 for pid,pd in ed['phases'].items():
  ph=phs[pid];ph['text']=pd['text'];chs={x['id']:x for x in ph['choices']}
  for cid,label in pd['labels'].items():chs[cid]['label']=label
  for cid,cd in pd.get('checks',{}).items():
   ch=chs[cid]
   if cd.get('text') is not None:ch['text']=cd['text']
   if cd.get('preview') is not None:ch['preview']=cd['preview']
   ch['check']['success']['text']=cd['success'];ch['check']['failure']['text']=cd['failure']
 p['events'][eid]['choices']=d['presentation'][eid]
assert mechanics()==before,'prose stage changed place-event mechanics'
gp.write_text(json.dumps(g,ensure_ascii=False,indent=2)+'\n');pp.write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n')
(root/'tests/world-events.test.mjs').write_text(WORLD_TEST)
pkgp=root/'package.json';pkg=json.loads(pkgp.read_text())
if 'tests/world-events.test.mjs' not in pkg['scripts']['test']:pkg['scripts']['test']+=' tests/world-events.test.mjs'
pkgp.write_text(json.dumps(pkg,ensure_ascii=False,indent=2)+'\n')
docp=root/'docs/ANCESTRY_TALENTS.md';s=docp.read_text();
if '## 阶段五：地点事件文本重构' not in s:docp.write_text(s+DOC_APPEND)
rp=root/'README.md';s=rp.read_text();
if '地点事件去模板化' not in s:rp.write_text(s+README_APPEND)
print('Stage 5 world prose applied; mechanics unchanged',hashlib.sha256(before.encode()).hexdigest())
